from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
X = partial(mk, "medication-induced", "medication-induced", "stethoscope")
DSM_X = DSM("Medication-Induced Movement Disorders and Other Adverse Effects of Medication")
CARBON = src("src-carbon-td", "Tardive dyskinesia prevalence in the period of second-generation antipsychotic use: a meta-analysis", "Journal of Clinical Psychiatry (Carbon et al.)", "https://www.psychiatrist.com/jcp/tardive-dyskinesia-prevalence", 2017, seen=True)
VMAT2 = src("src-vmat2-review", "Role of VMAT2 inhibitors in tardive dyskinesia management", "PubMed Central (PMC6802812)", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6802812/", seen=True, note="Not opened; one cited review was industry-sponsored.")
NMS_REV = src("src-nms-review", "Neuroleptic malignant syndrome: review", "Neuropsychiatric Disease and Treatment (10.2147/NDT.S118438)", "https://informahealthcare.com/doi/full/10.2147/NDT.S118438", seen=True, note="Not opened; figures from search snippets.")
HENSSLER = src("src-henssler-2024", "Incidence of antidepressant discontinuation symptoms: a systematic review and meta-analysis", "The Lancet Psychiatry (Henssler et al.), 11(7):526–535; summary via Psychiatric News Alert", "https://alert.psychnews.org/2024/06/1-in-6-who-stop-antidepressants.html", 2024, seen=True)
RCPSYCH_STOP = src("src-rcpsych-stopping", "Stopping antidepressants (patient information)", "Royal College of Psychiatrists", "https://www.rcpsych.ac.uk/news-and-features/latest-news/detail/2020/09/23/new-information-on-stopping-antidepressants", 2020, seen=True, note="News release seen; resource page not opened.")
X_COMMS = ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia", "hearing-voices-network-groups"]
X_NOTE = ["No doses or tapering schedules given; always 'with your prescriber'."]

CARDS.append(X("medication-induced-movement-disorders", "Medication-Induced Movement Disorders", "Movement side effects: stiffness, restlessness, tremor", ["extrapyramidal side effects (EPS)", "tardive dyskinesia (TD)", "akathisia", "drug-induced parkinsonism", "acute dystonia"], "G21.x / G24.x / G25.x",
 "Movement problems caused by psychiatric medication, especially antipsychotics: stiffness, tremor, inner restlessness, or involuntary movements.",
 "Some medications, mainly antipsychotics and a few others, can affect the brain's movement systems. Early effects include muscle spasms (dystonia), stiffness and tremor (parkinsonism), and an awful inner restlessness (akathisia). Tardive dyskinesia is a later effect: repetitive involuntary movements, often of the mouth, tongue, or limbs, that can persist. These aren't signs of the illness getting worse. Tell your prescriber early; most effects can be reduced by adjusting the medication or adding treatment.",
 ["I couldn't sit through a meal. I paced and paced and thought I was losing it. It was akathisia, and a dose change fixed it in days.", "My mum's mouth moved constantly and nobody at the home mentioned it. A new psychiatrist spotted tardive dyskinesia straight away."],
 ["Painful muscle spasms of the neck, jaw, or eyes soon after a dose change", "Stiffness, slowness, shuffling walk, or tremor", "Intense inner restlessness; needing to pace or shift constantly", "Repetitive involuntary movements of the mouth, tongue, face, or limbs that develop over time", "Movements that other people notice before you do"],
 [{"myth": "Restlessness or stiffness means the mental illness is getting worse.", "fact": "These are usually medication effects, and they're treatable. Mistaking akathisia for agitation can lead to dose increases that make it worse."},
  {"myth": "Tardive dyskinesia is untreatable, so there's no point mentioning it.", "fact": "Catching it early gives the most options, and newer medications specifically treat it. Always mention new movements."},
  {"myth": "You should stop the medication if you notice movements.", "fact": "Stopping suddenly can be dangerous. Tell your prescriber and decide together; adjustments are often enough."}],
 {"plain": "Around 1 in 4 people on long-term antipsychotics has some tardive dyskinesia, with lower rates on newer medications. Akathisia and parkinsonism are common early on.", "figure": "Tardive dyskinesia mean prevalence 25.3% (20.7% on second-generation, 30.0% on first-generation antipsychotics; meta-analysis of 41 studies, 2000–2015)", "source_ref": "src-carbon-td"},
 {"plain_summary": "Your prescriber may lower the dose, switch to a medication less likely to cause movement effects, or add a medication that counters the effect. Akathisia often responds to dose changes and specific add-on medications. Tardive dyskinesia can be treated with newer medications (VMAT2 inhibitors) in some countries, alongside review of the antipsychotic. Regular movement checks, ideally every few months, catch problems early. Never stop or change doses on your own.",
  "evidence_based_options": ["Dose reduction or switch to a lower-risk antipsychotic, with your prescriber", "Add-on medication for dystonia, parkinsonism, or akathisia, prescribed and monitored by a doctor", "VMAT2 inhibitors for tardive dyskinesia where available, prescribed and monitored by a doctor", "Regular structured movement monitoring (for example, the AIMS check)"],
  "self_help_that_supports_care": ["Telling your prescriber about any new movement, stiffness, or restlessness", "Asking for a movement check at each review", "Keeping a short note or video of movements to show the clinician", "Peer groups where people share what helped"],
  "guideline_refs": ["src-carbon-td", "src-vmat2-review"]},
 "Tell your prescriber as soon as you notice stiffness, tremor, restlessness, or involuntary movements. Seek urgent care for a sudden painful spasm of the neck, jaw, eyes, or throat, or any trouble swallowing or breathing, which can be acute dystonia and is treatable quickly.",
 "Movement problems from Parkinson's disease, Huntington's, tics, anxiety, or other medical conditions are assessed separately. Agitation from the illness itself can look like akathisia; the difference matters for treatment.",
 "Most movement effects can be reduced or managed. Being heard by a prescriber who checks regularly makes all the difference.",
 ["neuroleptic-malignant-syndrome", "schizophrenia", "bipolar-i-disorder", "parkinsons-disease-neurocognitive-disorder", "tic-disorders"],
 ["antipsychotic", "side-effects", "long-acting-injectable", "informed-consent"],
 X_COMMS, ("Soft line illustration of a person and a pharmacist talking across a counter, a medication box and a notepad between them, calm light. Pastel teal and sand.", "A person talks with a pharmacist across a counter."),
 [DSM_X, CARBON, VMAT2], qs=["Add a prescribing guideline reference.", "Pharmacist or psychiatrist to review."], notes=X_NOTE,
 subs=[{"title": "Acute dystonia", "icd10cm_code": "G24.02", "text": "Sudden muscle spasms within days of starting or increasing a dose. Treated quickly with medication."}, {"title": "Akathisia", "icd10cm_code": "G25.71", "text": "Inner restlessness and the need to keep moving. Often mistaken for anxiety or agitation."}, {"title": "Drug-induced parkinsonism", "icd10cm_code": "G21.11", "text": "Stiffness, tremor, slow movement, reduced facial expression."}, {"title": "Tardive dyskinesia", "icd10cm_code": "G24.01", "text": "Involuntary repetitive movements that develop after months or years and may persist."}]))

CARDS.append(X("neuroleptic-malignant-syndrome", "Neuroleptic Malignant Syndrome", "A rare, dangerous reaction to antipsychotic medication", ["NMS"], "G21.0",
 "A rare emergency reaction to antipsychotics: high fever, severe muscle stiffness, confusion, and unstable pulse or blood pressure.",
 "Neuroleptic malignant syndrome is a rare but life-threatening reaction to antipsychotic medication, and occasionally to other drugs that affect dopamine, or to suddenly stopping Parkinson's medication. It usually develops within weeks of starting or increasing a dose. The signs are a high fever, severe muscle stiffness, confusion or reduced consciousness, and a fast or irregular pulse, sweating, or swinging blood pressure. It needs emergency hospital care. With quick treatment most people recover fully.",
 ["He went stiff and burning hot over two days and we thought it was flu. The ambulance crew knew what it was. He's fine now, on a different medication.", "Every psychiatrist since has asked about it. I carry a card in my wallet that says NMS, 2019."],
 ["High fever with no obvious infection", "Severe muscle stiffness, often described as 'lead pipe'", "Confusion, drowsiness, or reduced consciousness", "Fast or irregular heartbeat, sweating, blood pressure swings", "Usually within weeks of starting or increasing an antipsychotic"],
 [{"myth": "It's so rare it isn't worth knowing about.", "fact": "It's rare, but it can kill, and knowing the signs is what gets people to hospital in time. Everyone on antipsychotics, and their families, should know them."},
  {"myth": "After NMS you can never take antipsychotics again.", "fact": "Many people can later restart a different antipsychotic cautiously, under close monitoring, when the benefits are clear."}],
 {"plain": "NMS affects well under 1 in 100 people taking antipsychotics, with estimates ranging from a tiny fraction of a percent up to a few percent in older studies. Deaths have fallen with better recognition.", "figure": "Incidence estimates about 0.02%–3% in reviews; mortality around 5%–12% in recent estimates, down from up to 30% historically", "source_ref": "src-nms-review", "note": "Wide variation; needs a primary citation."},
 {"plain_summary": "NMS is treated in hospital: the medication is stopped, the body is cooled, fluids are given, and the heart, kidneys, and muscles are monitored. Specific medications are sometimes used. Recovery usually takes days to a couple of weeks. Afterwards, the care team reviews whether and how to restart an antipsychotic, usually a different one, at a low dose with close monitoring.",
  "evidence_based_options": ["Emergency assessment and stopping the triggering medication", "Supportive hospital care: cooling, fluids, monitoring", "Specific medications in some cases, given in hospital", "Careful, monitored reintroduction of a different antipsychotic later, if needed"],
  "self_help_that_supports_care": ["Knowing the warning signs if you or someone you care for takes antipsychotics", "Not stopping Parkinson's or antipsychotic medication suddenly without medical advice", "Carrying a note of your medications", "Telling any new prescriber about a past NMS"],
  "guideline_refs": ["src-nms-review"]},
 "If someone taking an antipsychotic develops a high fever with severe stiffness and confusion, call emergency services or go to an emergency department now. Don't wait to see if it passes.",
 "Fever from an infection, stiffness from ordinary side effects, catatonia, serotonin syndrome, and heatstroke can look similar and are sorted out in hospital.",
 "Recognised and treated quickly, most people recover completely and go on to find a medication that suits them.",
 ["medication-induced-movement-disorders", "schizophrenia", "delirium", "catatonia"],
 ["antipsychotic", "side-effects", "inpatient"],
 X_COMMS, ("Soft line illustration of a hospital room with a person resting comfortably, a nurse checking a chart, a window with soft daylight and a plant. Pastel teal and white.", "A person rests comfortably in a hospital room while a nurse checks a chart."),
 [DSM_X, NMS_REV], qs=["Find a primary incidence source.", "Psychiatrist to review."], sens="elevated", notes=X_NOTE + ["Medical emergency card; crisis strip points to emergency services."]))

CARDS.append(X("antidepressant-discontinuation-syndrome", "Antidepressant Discontinuation Syndrome", "Withdrawal-like symptoms when stopping antidepressants", ["antidepressant withdrawal", "SSRI discontinuation syndrome", "'brain zaps'"], "T43.205A / D / S",
 "Physical and emotional symptoms in the days after stopping or sharply reducing an antidepressant, usually brief but sometimes severe.",
 "When an antidepressant is stopped suddenly or reduced too fast, some people get symptoms within a few days: dizziness, nausea, flu-like feelings, 'electric shock' sensations, vivid dreams, trouble sleeping, anxiety, and irritability. It's not addiction, and it's not the depression returning, though it can be confused with relapse. Symptoms are usually mild and pass within two weeks; for a smaller number they're severe or longer-lasting. Reducing slowly, in steps agreed with your prescriber, prevents or eases most of it.",
 ["I thought I was relapsing. The dizziness and the brain zaps started three days after I ran out. My GP explained and we tapered properly.", "Coming off took me a year of tiny steps. Slow was fine. Fast had been awful."],
 ["Dizziness, nausea, headache, or flu-like feelings within days of stopping", "Brief 'electric shock' sensations, often with eye or head movement", "Vivid dreams, insomnia, anxiety, irritability, or low mood", "Usually begins within a week and eases over one to two weeks", "More likely with sudden stops and with certain antidepressants"],
 [{"myth": "Discontinuation symptoms mean you're addicted.", "fact": "Antidepressants don't cause craving or compulsive use. The body adjusts to them, so stopping needs to be gradual, which is different from addiction."},
  {"myth": "Symptoms after stopping mean you'll always need the medication.", "fact": "Discontinuation symptoms are the body adjusting, not proof you need the drug. A slower taper usually resolves them. Relapse is a separate question to review with your prescriber."},
  {"myth": "Everyone gets terrible withdrawal.", "fact": "A 2024 analysis found about 1 in 6 or 7 people get symptoms beyond placebo, and about 1 in 35 get severe symptoms. Most people stop without major difficulty."}],
 {"plain": "After accounting for placebo effects, roughly 1 in 6 to 7 people who stop an antidepressant get at least one discontinuation symptom, and about 1 in 35 get severe symptoms.", "figure": "About 15% with any symptom and about 3% with severe symptoms after adjusting for placebo; 31% unadjusted (Lancet Psychiatry meta-analysis, 2024)", "source_ref": "src-henssler-2024"},
 {"plain_summary": "The main approach is prevention: when it's time to stop, reduce the dose gradually in steps, over weeks to months depending on the medication and the person, with your prescriber. If symptoms appear, going back to the previous dose and reducing more slowly usually settles them. Some medications may be switched to a longer-acting one to make tapering easier. The Royal College of Psychiatrists and NICE both recommend tapering and shared decisions. Never stop suddenly without advice.",
  "evidence_based_options": ["Gradual dose reduction planned with your prescriber", "Returning to the previous dose and tapering more slowly if symptoms appear", "Switching to a longer-acting antidepressant to ease tapering, in some cases", "Monitoring for relapse separately from discontinuation symptoms"],
  "self_help_that_supports_care": ["Not running out of medication; keep a supply during a taper", "Tracking symptoms and mood so you and your prescriber can tell them apart", "Choosing a calm period to taper, with support in place", "Reading patient guidance from the Royal College of Psychiatrists or NICE"],
  "guideline_refs": ["src-henssler-2024", "src-rcpsych-stopping"]},
 "If you want to stop an antidepressant, talk to your prescriber first and make a plan. If you've stopped and feel dizzy, sick, or strange, contact them; it's usually easy to fix. If your mood drops sharply or you have thoughts of ending your life, use the crisis strip now.",
 "Depression or anxiety returning after stopping is relapse, not discontinuation; it tends to come later and build slowly. Side effects while taking the medication are a different issue. Stopping a benzodiazepine or opioid is withdrawal and needs its own medical plan.",
 "Most people come off antidepressants without serious trouble when it's done gradually. Slow is the whole trick.",
 ["major-depressive-disorder", "generalized-anxiety-disorder", "panic-disorder", "medication-induced-movement-disorders"],
 ["antidepressant", "ssri", "snri", "tapering", "withdrawal", "relapse", "side-effects"],
 X_COMMS, ("Soft line illustration of a person and a doctor looking at a calendar together, a pill organiser on the desk, a mug of tea. Pastel teal and lavender.", "A person and a doctor look at a calendar together."),
 [DSM_X, HENSSLER, RCPSYCH_STOP], qs=["Add NICE NG222 depression guideline reference on stopping antidepressants."], notes=X_NOTE))
